class OmniDebertaImageStem(nn.Module):
    """Image -> patch tokens: a linear projection of every patch plus a learned row and column embedding."""

    def __init__(self, config: OmniDebertaConfig):
        super().__init__()
        self.patch_size = config.patch_size
        self.grid = config.image_size // config.patch_size
        self.patch_proj = nn.Linear(config.num_channels * config.patch_size**2, config.hidden_size, bias=False)
        self.row_embeddings = nn.Embedding(self.grid, config.hidden_size)
        self.column_embeddings = nn.Embedding(self.grid, config.hidden_size)
        self.layer_norm = nn.LayerNorm(config.hidden_size, eps=config.layer_norm_eps)

    def forward(self, pixel_values: torch.Tensor) -> torch.Tensor:
        """`(images, channels, height, width)` -> `(images, patches, hidden_size)`, patches in row-major order."""
        images, channels = pixel_values.shape[:2]
        grid, patch = self.grid, self.patch_size
        patches = pixel_values.to(self.patch_proj.weight.dtype)
        patches = patches.reshape(images, channels, grid, patch, grid, patch).permute(0, 2, 4, 3, 5, 1)
        patches = self.patch_proj(patches.reshape(images, grid * grid, patch * patch * channels))
        index = torch.arange(grid, device=patches.device)
        position = self.row_embeddings(index)[:, None, :] + self.column_embeddings(index)[None, :, :]
        return self.layer_norm(patches + position.reshape(1, grid * grid, -1).to(patches.dtype))


class OmniDebertaAudioStem(nn.Module):
    """Log-mel frames -> audio tokens: two 3x3 stride-2 convolutions and a projection, four frames per token."""

    def __init__(self, config: OmniDebertaConfig):
        super().__init__()
        first, second = config.audio_conv_channels
        self.conv1 = nn.Conv2d(1, first, kernel_size=3, stride=2, padding=1, bias=False)
        self.norm1 = nn.LayerNorm(first, eps=config.layer_norm_eps)
        self.conv2 = nn.Conv2d(first, second, kernel_size=3, stride=2, padding=1, bias=False)
        self.norm2 = nn.LayerNorm(second, eps=config.layer_norm_eps)
        self.proj = nn.Linear(second * (config.num_mel_bins // 4), config.hidden_size, bias=False)
        self.layer_norm = nn.LayerNorm(config.hidden_size, eps=config.layer_norm_eps)

    @staticmethod
    def num_tokens(num_frames: torch.Tensor) -> torch.Tensor:
        """Audio tokens made from `num_frames` mel frames."""
        tokens = (num_frames - 1) // 2 + 1
        return (tokens - 1) // 2 + 1

    def forward(self, input_features: torch.Tensor, input_features_mask: torch.Tensor) -> torch.Tensor:
        """`(clips, frames, mel)` and the frame mask -> the tokens of the real frames, `(tokens, hidden_size)`."""
        mask = input_features_mask.bool()
        hidden = (input_features * mask[..., None]).unsqueeze(1).to(self.conv1.weight.dtype)
        hidden = torch.relu(self.norm1(self.conv1(hidden).permute(0, 2, 3, 1))).permute(0, 3, 1, 2)
        hidden = hidden * mask[:, ::2][:, None, :, None]
        hidden = torch.relu(self.norm2(self.conv2(hidden).permute(0, 2, 3, 1)))  # (clips, tokens, mel / 4, channels)
        hidden = self.layer_norm(self.proj(hidden.flatten(2)))
        valid = torch.arange(hidden.shape[1], device=hidden.device)[None, :] < self.num_tokens(mask.sum(1))[:, None]
        return hidden[valid]


MODALITIES = ("text", "image", "audio")
IMAGE = 1
AUDIO = 2


class OmniDebertaEmbeddings(nn.Module):
    """Words, image patches and audio frames -> one sequence of `hidden_size` vectors."""

    def __init__(self, config: OmniDebertaConfig):
        super().__init__()
        self.word_embeddings = nn.Embedding(config.vocab_size, config.embedding_size, padding_idx=config.pad_token_id)
        # CODEPATH: absolute positions of DeBERTa-v2; released checkpoints use relative positions only.
        self.position_embeddings = (
            nn.Embedding(config.max_position_embeddings, config.embedding_size)
            if config.position_biased_input
            else None
        )
        # CODEPATH: factorized word embeddings (embedding_size < hidden_size), as in all released checkpoints.
        self.embed_proj = (
            nn.Linear(config.embedding_size, config.hidden_size, bias=False)
            if config.embedding_size != config.hidden_size
            else None
        )
        self.LayerNorm = nn.LayerNorm(config.hidden_size, eps=config.layer_norm_eps)
        # CODEPATH: models for one medium (e.g. speech recognition) are built without the other stem.
        self.image_stem = OmniDebertaImageStem(config) if "image" in config.modalities else None
        # CODEPATH: models for one medium (e.g. referring segmentation) are built without the other stem.
        self.audio_stem = OmniDebertaAudioStem(config) if "audio" in config.modalities else None
        self.modality_embeddings = nn.Embedding(len(MODALITIES), config.hidden_size)
        self.dropout = nn.Dropout(config.hidden_dropout_prob)

    def forward(
        self,
        input_ids: torch.LongTensor,
        attention_mask: torch.Tensor,
        modality_ids: torch.LongTensor,
        pixel_values: torch.Tensor | None = None,
        input_features: torch.Tensor | None = None,
        input_features_mask: torch.Tensor | None = None,
    ) -> torch.Tensor:
        embeddings = self.word_embeddings(input_ids)
        if self.position_embeddings is not None:
            positions = torch.arange(input_ids.shape[1], device=input_ids.device)
            embeddings = embeddings + self.position_embeddings(positions)[None]
        if self.embed_proj is not None:
            embeddings = self.embed_proj(embeddings)
        embeddings = self.LayerNorm(embeddings)

        if pixel_values is not None:
            if self.image_stem is None:
                raise ValueError("This model is built without the image modality.")
            patches = self.image_stem(pixel_values)
            image_mask = modality_ids == IMAGE
            torch_compilable_check(
                image_mask.sum() == patches.shape[0] * patches.shape[1],
                lambda: f"Got {patches.shape[0] * patches.shape[1]} image patches for {int(image_mask.sum())} "
                "image placeholder tokens",
            )
            patches = patches.reshape(-1, patches.shape[-1]).to(embeddings.dtype)
            embeddings = embeddings.masked_scatter(image_mask[..., None], patches)

        if input_features is not None:
            if self.audio_stem is None:
                raise ValueError("This model is built without the audio modality.")
            if input_features_mask is None:
                input_features_mask = torch.ones(input_features.shape[:2], dtype=torch.bool, device=embeddings.device)
            frames = self.audio_stem(input_features, input_features_mask).to(embeddings.dtype)
            audio_mask = modality_ids == AUDIO
            torch_compilable_check(
                audio_mask.sum() == frames.shape[0],
                lambda: f"Got {frames.shape[0]} audio tokens for {int(audio_mask.sum())} audio placeholder tokens",
            )
            embeddings = embeddings.masked_scatter(audio_mask[..., None], frames)

        embeddings = embeddings + self.modality_embeddings(modality_ids).to(embeddings.dtype)
        embeddings = embeddings * attention_mask[..., None].to(embeddings.dtype)
        return self.dropout(embeddings)


# NOTE: this differs on purpose from the eager attention of other models that support a position bias
# (e.g. `inkling`), in order to stay equivalent to the original conformer implementation:
# - no `repeat_kv` as these models do not use GQA
# - the softmax stays in the input dtype instead of being upcast to fp32
def eager_attention_forward(
    module: nn.Module,
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    attention_mask: torch.Tensor | None,
    scaling: float | None = None,
    dropout: float = 0.0,
    position_bias: torch.Tensor | None = None,
    **kwargs: Unpack[TransformersKwargs],
):
    if scaling is None:
        scaling = query.size(-1) ** -0.5

    attn_weights = torch.matmul(query, key.transpose(2, 3)) * scaling

    if position_bias is not None:
        attn_weights = attn_weights + position_bias
    if attention_mask is not None:
        attn_weights = attn_weights + attention_mask

    attn_weights = nn.functional.softmax(attn_weights, dim=-1)
    attn_weights = nn.functional.dropout(attn_weights, p=dropout, training=module.training)

    attn_output = torch.matmul(attn_weights, value)
    attn_output = attn_output.transpose(1, 2).contiguous()

    return attn_output, attn_weights


class OmniDebertaSelfAttention(nn.Module):
    """DeBERTa-v2 disentangled self-attention; the relative position of every query-key pair is an input."""

    def __init__(self, config: OmniDebertaConfig):
        super().__init__()
        self.config = config
        self.num_attention_heads = config.num_attention_heads
        self.attention_head_size = config.hidden_size // config.num_attention_heads
        self.is_causal = False
        self.query_proj = nn.Linear(config.hidden_size, config.hidden_size)
        self.key_proj = nn.Linear(config.hidden_size, config.hidden_size)
        self.value_proj = nn.Linear(config.hidden_size, config.hidden_size)

        # CODEPATH: relative_attention=False is plain content attention, as in DeBERTa-v2.
        self.pos_att_type = config.pos_att_type if config.relative_attention else []
        self.share_att_key = config.share_att_key
        max_relative_positions = config.max_relative_positions
        if max_relative_positions < 1:
            max_relative_positions = config.max_position_embeddings
        self.pos_ebd_size = config.position_buckets if config.position_buckets > 0 else max_relative_positions
        # CODEPATH: released checkpoints share the content projections (share_att_key=True).
        if not config.share_att_key:
            if "c2p" in self.pos_att_type:
                self.pos_key_proj = nn.Linear(config.hidden_size, config.hidden_size)
            if "p2c" in self.pos_att_type:
                self.pos_query_proj = nn.Linear(config.hidden_size, config.hidden_size)
        self.pos_dropout = nn.Dropout(config.hidden_dropout_prob)
        self.dropout = config.attention_probs_dropout_prob
        self.scale = math.sqrt(self.attention_head_size * (1 + len(self.pos_att_type)))

    def split_heads(self, hidden_states: torch.Tensor) -> torch.Tensor:
        shape = (*hidden_states.shape[:-1], self.num_attention_heads, self.attention_head_size)
        return hidden_states.view(shape).transpose(-3, -2)

    def position_bias(
        self,
        query: torch.Tensor,
        key: torch.Tensor,
        relative_pos: torch.Tensor,
        rel_embeddings: torch.Tensor,
    ) -> torch.Tensor | None:
        """The c2p and p2c terms, divided by the scale: `(batch, heads, length, length)`, or None."""
        if not self.pos_att_type:
            return None
        span = self.pos_ebd_size
        rel_embeddings = self.pos_dropout(rel_embeddings[: 2 * span])[None]
        relative_pos = relative_pos[:, None].expand(-1, self.num_attention_heads, -1, -1)
        bias = 0
        if "c2p" in self.pos_att_type:
            pos_key = self.split_heads((self.key_proj if self.share_att_key else self.pos_key_proj)(rel_embeddings))
            # Trained c2p terms hold a large constant per query (the query against the mean position key); the
            # softmax ignores it, but in half precision it swallows the part that differs between keys. Centering the
            # position keys removes it exactly.
            pos_key = pos_key - pos_key.mean(-2, keepdim=True)
            c2p = torch.matmul(query, pos_key.transpose(-1, -2))
            index = torch.clamp(relative_pos + span, 0, 2 * span - 1).expand(c2p.shape[0], -1, -1, -1)
            bias = bias + torch.gather(c2p, -1, index)
        if "p2c" in self.pos_att_type:
            pos_query = self.split_heads(
                (self.query_proj if self.share_att_key else self.pos_query_proj)(rel_embeddings)
            )
            p2c = torch.matmul(key, pos_query.transpose(-1, -2))
            index = torch.clamp(-relative_pos + span, 0, 2 * span - 1).expand(p2c.shape[0], -1, -1, -1)
            bias = bias + torch.gather(p2c, -1, index).transpose(-1, -2)
        return bias / self.scale

    def forward(
        self,
        hidden_states: torch.Tensor,
        attention_mask: torch.Tensor | None = None,
        relative_pos: torch.Tensor | None = None,
        rel_embeddings: torch.Tensor | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple[torch.Tensor, torch.Tensor | None]:
        query = self.split_heads(self.query_proj(hidden_states))
        key = self.split_heads(self.key_proj(hidden_states))
        value = self.split_heads(self.value_proj(hidden_states))
        position_bias = self.position_bias(query, key, relative_pos, rel_embeddings)
        if position_bias is not None:
            position_bias = position_bias.to(query.dtype)

        attention_interface: Callable = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, eager_attention_forward
        )
        attn_output, attn_weights = attention_interface(
            self,
            query,
            key,
            value,
            attention_mask,
            dropout=self.dropout if self.training else 0.0,
            scaling=1 / self.scale,
            position_bias=position_bias,
            **kwargs,
        )
        attn_output = attn_output.reshape(*hidden_states.shape[:-1], -1).contiguous()
        return attn_output, attn_weights


class OmniDebertaSelfOutput(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.dense = nn.Linear(config.hidden_size, config.hidden_size)
        self.LayerNorm = LayerNorm(config.hidden_size, config.layer_norm_eps)
        self.dropout = nn.Dropout(config.hidden_dropout_prob)

    def forward(self, hidden_states, input_tensor):
        hidden_states = self.dense(hidden_states)
        hidden_states = self.dropout(hidden_states)
        hidden_states = self.LayerNorm(hidden_states + input_tensor)
        return hidden_states


class OmniDebertaAttention(nn.Module):
    def __init__(self, config: OmniDebertaConfig):
        super().__init__()
        self.self = OmniDebertaSelfAttention(config)
        self.output = OmniDebertaSelfOutput(config)

    def forward(
        self,
        hidden_states: torch.Tensor,
        attention_mask: torch.Tensor | None = None,
        relative_pos: torch.Tensor | None = None,
        rel_embeddings: torch.Tensor | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> torch.Tensor:
        self_output, _ = self.self(hidden_states, attention_mask, relative_pos, rel_embeddings, **kwargs)
        return self.output(self_output, hidden_states)


class OmniDebertaIntermediate(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.dense = nn.Linear(config.hidden_size, config.intermediate_size)
        if isinstance(config.hidden_act, str):
            self.intermediate_act_fn = ACT2FN[config.hidden_act]
        else:
            self.intermediate_act_fn = config.hidden_act

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        hidden_states = self.dense(hidden_states)
        hidden_states = self.intermediate_act_fn(hidden_states)
        return hidden_states


class OmniDebertaOutput(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.dense = nn.Linear(config.intermediate_size, config.hidden_size)
        self.LayerNorm = LayerNorm(config.hidden_size, config.layer_norm_eps)
        self.dropout = nn.Dropout(config.hidden_dropout_prob)
        self.config = config

    def forward(self, hidden_states, input_tensor):
        hidden_states = self.dense(hidden_states)
        hidden_states = self.dropout(hidden_states)
        hidden_states = self.LayerNorm(hidden_states + input_tensor)
        return hidden_states


class OmniDebertaExpertRouting(NamedTuple):
    """Tokens grouped by feed-forward expert; built once per forward pass and used by every layer."""

    order: torch.Tensor  # flattened token indices, sorted by expert
    inverse: torch.Tensor  # where every token sits in `order`
    counts: list[int]  # tokens per expert (text, image, audio)


class OmniDebertaLayer(GradientCheckpointingLayer):
    def __init__(self, config: OmniDebertaConfig):
        super().__init__()
        self.attention = OmniDebertaAttention(config)
        # the feed-forward block, or with `modal_experts` the text expert
        self.intermediate = OmniDebertaIntermediate(config)
        self.output = OmniDebertaOutput(config)
        # CODEPATH: stage-1 checkpoints have one feed-forward block, the released ones one expert per modality.
        if config.modal_experts:
            self.image_intermediate = OmniDebertaIntermediate(config) if "image" in config.modalities else None
            self.image_output = OmniDebertaOutput(config) if "image" in config.modalities else None
            self.audio_intermediate = OmniDebertaIntermediate(config) if "audio" in config.modalities else None
            self.audio_output = OmniDebertaOutput(config) if "audio" in config.modalities else None

    def experts(self) -> list[tuple[nn.Module, nn.Module] | None]:
        """`(intermediate, output)` of the text, image and audio experts (None for a modality not built)."""
        image = (self.image_intermediate, self.image_output) if self.image_intermediate is not None else None
        audio = (self.audio_intermediate, self.audio_output) if self.audio_intermediate is not None else None
        return [(self.intermediate, self.output), image, audio]

    def forward(
        self,
        hidden_states: torch.Tensor,
        attention_mask: torch.Tensor | None = None,
        relative_pos: torch.Tensor | None = None,
        rel_embeddings: torch.Tensor | None = None,
        routing: OmniDebertaExpertRouting | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> torch.Tensor:
        attention_output = self.attention(hidden_states, attention_mask, relative_pos, rel_embeddings, **kwargs)
        if routing is None:
            return self.output(self.intermediate(attention_output), attention_output)
        shape = attention_output.shape
        groups = attention_output.reshape(-1, shape[-1])[routing.order].split(routing.counts)
        outputs = []
        for expert, group in zip(self.experts(), groups):
            if expert is not None:
                intermediate, output = expert
                outputs.append(output(intermediate(group), group))
        return torch.cat(outputs)[routing.inverse].view(shape)


def make_log_bucket_position(relative_pos, bucket_size: int, max_position: int):
    sign = torch.sign(relative_pos)
    mid = bucket_size // 2
    abs_pos = torch.where(
        (relative_pos < mid) & (relative_pos > -mid),
        torch.tensor(mid - 1).type_as(relative_pos),
        torch.abs(relative_pos),
    )
    log_pos = (
        torch.ceil(torch.log(abs_pos / mid) / torch.log(torch.tensor((max_position - 1) / mid)) * (mid - 1)) + mid
    )
    bucket_pos = torch.where(abs_pos <= mid, relative_pos.type_as(log_pos), log_pos * sign)
    return bucket_pos


def build_relative_position(positions: torch.Tensor, bucket_size: int = -1, max_position: int = -1) -> torch.Tensor:
    """Relative position (bucket) of every query-key pair, from token positions of shape `(..., length)`."""
    relative = positions[..., :, None] - positions[..., None, :]
    if bucket_size > 0 and max_position > 0:
        relative = make_log_bucket_position(relative, bucket_size, max_position)
    return relative.long()


class OmniDebertaEncoder(nn.Module):
    def __init__(self, config: OmniDebertaConfig):
        super().__init__()
        self.config = config
        self.layer = nn.ModuleList([OmniDebertaLayer(config) for _ in range(config.num_hidden_layers)])
        self.max_relative_positions = config.max_relative_positions
        if self.max_relative_positions < 1:
            self.max_relative_positions = config.max_position_embeddings
        self.position_buckets = config.position_buckets
        size = self.position_buckets if self.position_buckets > 0 else self.max_relative_positions
        # CODEPATH: relative_attention=False has no relative embeddings, as in DeBERTa-v2.
        self.rel_embeddings = nn.Embedding(2 * size, config.hidden_size) if config.relative_attention else None
        norm_rel_ebd = [x.strip() for x in config.norm_rel_ebd.lower().split("|")]
        # CODEPATH: released checkpoints normalize the relative embeddings (norm_rel_ebd="layer_norm").
        self.LayerNorm = (
            nn.LayerNorm(config.hidden_size, config.layer_norm_eps)
            if config.relative_attention and "layer_norm" in norm_rel_ebd
            else None
        )
        self.relative_2d_layers = {int(i) for i in config.relative_2d_layers}
        self.gradient_checkpointing = False

    def get_rel_embedding(self) -> torch.Tensor | None:
        if self.rel_embeddings is None:
            return None
        rel_embeddings = self.rel_embeddings.weight
        if self.LayerNorm is not None:
            rel_embeddings = self.LayerNorm(rel_embeddings)
        return rel_embeddings

    def forward(
        self,
        hidden_states: torch.Tensor,
        attention_mask: torch.Tensor | None = None,
        positions_2d: torch.Tensor | None = None,
        routing: OmniDebertaExpertRouting | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> torch.Tensor:
        """
        positions_2d `(batch, length)`: token positions in the layers of `config.relative_2d_layers`; routing: the
        feed-forward expert of every token (`config.modal_experts`).
        """
        rel_embeddings = self.get_rel_embedding()
        sequential = grid = None
        if rel_embeddings is not None:
            order = torch.arange(hidden_states.shape[1], device=hidden_states.device)[None]
            sequential = build_relative_position(order, self.position_buckets, self.max_relative_positions)
            if positions_2d is not None:
                grid = build_relative_position(positions_2d, self.position_buckets, self.max_relative_positions)

        for index, layer in enumerate(self.layer, start=1):
            relative_pos = grid if grid is not None and index in self.relative_2d_layers else sequential
            hidden_states = layer(hidden_states, attention_mask, relative_pos, rel_embeddings, routing, **kwargs)
        return hidden_states


@auto_docstring
class OmniDebertaPreTrainedModel(PreTrainedModel):
    config: OmniDebertaConfig
    base_model_prefix = "model"
    main_input_name = "input_ids"
    input_modalities = ("text", "image", "audio")
    supports_gradient_checkpointing = True
    _no_split_modules = ["OmniDebertaLayer"]
    _supports_sdpa = True
    _supports_flex_attn = True
    _supports_flash_attn = False  # the relative position terms are an additive bias
    _can_record_outputs = {
        "hidden_states": OmniDebertaLayer,
        "attentions": OmniDebertaSelfAttention,
    }
    # a checkpoint holds the weights of every head and modality; a model loads the ones it has (the weights of a
    # modality it is built without, see `config.modalities`, are only unexpected then)
    _keys_to_ignore_on_load_unexpected = [
        r"^(lm_head|rtd_head)\.",
        r"^segment_(query|key|box)\.",
        r"^model\.pooler\.",
        r"embeddings\.(image|audio)_stem\.",
        r"\.(image|audio)_(intermediate|output)\.",
    ]

    def __init__(self, config: OmniDebertaConfig, *inputs, **kwargs):
        # task heads tied to a medium (speech recognition, referring segmentation) build only their modalities
        if set(config.modalities) - set(self.input_modalities):
            config = copy.deepcopy(config)
            config.modalities = [m for m in config.modalities if m in self.input_modalities]
        super().__init__(config, *inputs, **kwargs)

    @torch.no_grad()
    def _init_weights(self, module):
        super()._init_weights(module)
        if isinstance(module, OmniDebertaLMHead):
            init.zeros_(module.bias)


# rows of `OmniDebertaEmbeddings.modality_embeddings` and indices of the feed-forward experts
TEXT = 0


@auto_docstring(
    custom_intro="""
    The bare OmniDeBERTa encoder: text, images and audio in one sequence. `pooler_output` is the sequence embedding:
    the L2-normalized projection of the `[EMBED]` state.
    """
)
class OmniDebertaModel(OmniDebertaPreTrainedModel):
    def __init__(self, config: OmniDebertaConfig, add_pooling_layer: bool = True):
        r"""
        add_pooling_layer (`bool`, *optional*, defaults to `True`):
            Whether to build the projection of the sequence embedding (`pooler_output`). The task heads leave it out.
        """
        super().__init__(config)
        self.embeddings = OmniDebertaEmbeddings(config)
        self.encoder = OmniDebertaEncoder(config)
        self.pooler = nn.Linear(config.hidden_size, config.projection_dim) if add_pooling_layer else None
        self.post_init()

    def get_input_embeddings(self):
        return self.embeddings.word_embeddings

    def set_input_embeddings(self, value):
        self.embeddings.word_embeddings = value

    def get_modality_ids(self, input_ids: torch.LongTensor) -> torch.LongTensor:
        """0 for text, 1 for image patch placeholders, 2 for audio placeholders."""
        modality_ids = torch.zeros_like(input_ids)
        modality_ids = modality_ids.masked_fill(input_ids == self.config.image_token_id, IMAGE)
        return modality_ids.masked_fill(input_ids == self.config.audio_token_id, AUDIO)

    def get_positions_2d(self, modality_ids: torch.LongTensor) -> torch.LongTensor:
        """
        Token positions in the layers with 2-D relative positions. The patch at `(row, column)` of an image sits at
        `first + row * relative_2d_stride + column` (`first`: the position of its first patch); whatever follows an
        image continues after its last patch. Positions are unique inside a sequence.
        """
        grid = self.config.image_size // self.config.patch_size
        extra = self.config.relative_2d_stride - grid
        is_patch = (modality_ids == IMAGE).long()
        index = is_patch.cumsum(1) - is_patch  # patches of the sequence before this token
        finished = index // (grid * grid)  # images completed before this token
        row = torch.where(is_patch.bool(), (index % (grid * grid)) // grid, torch.zeros_like(index))
        shift = extra * ((grid - 1) * finished + row)
        return torch.arange(modality_ids.shape[1], device=modality_ids.device)[None] + shift

    def get_expert_routing(
        self, input_ids: torch.LongTensor, modality_ids: torch.LongTensor
    ) -> OmniDebertaExpertRouting:
        """Feed-forward expert of every token (see `config.modal_experts`), grouped for the layers."""
        medium = torch.where(
            (modality_ids == IMAGE).any(1), IMAGE, torch.where((modality_ids == AUDIO).any(1), AUDIO, TEXT)
        )
        routed = torch.tensor(self.config.expert_routed_token_ids, device=input_ids.device)
        special = (modality_ids == TEXT) & torch.isin(input_ids, routed)
        expert_ids = torch.where(special, medium[:, None], modality_ids).reshape(-1)
        order = torch.argsort(expert_ids, stable=True)
        inverse = torch.empty_like(order).scatter_(0, order, torch.arange(order.numel(), device=order.device))
        counts = torch.bincount(expert_ids, minlength=len(MODALITIES))
        return OmniDebertaExpertRouting(order, inverse, counts.tolist())

    def get_pool_positions(self, input_ids: torch.LongTensor) -> torch.LongTensor:
        """Position of the pooled token of every sequence: the first `[EMBED]` (the first token if a sequence has
        none) with `config.embed_token_pooling`, else `[CLS]` (0)."""
        # CODEPATH: released checkpoints pool at [EMBED]; [CLS] pooling is the DeBERTa-v2 default.
        if not self.config.embed_token_pooling:
            return torch.zeros(input_ids.shape[0], dtype=torch.long, device=input_ids.device)
        return (input_ids == self.config.embed_token_id).int().argmax(1)

    @capture_outputs
    @auto_docstring
    def forward(
        self,
        input_ids: torch.LongTensor,
        attention_mask: torch.Tensor | None = None,
        pixel_values: torch.FloatTensor | None = None,
        input_features: torch.FloatTensor | None = None,
        input_features_mask: torch.Tensor | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> BaseModelOutputWithPooling:
        r"""
        input_ids (`torch.LongTensor` of shape `(batch_size, sequence_length)`):
            Token ids made by [`OmniDebertaProcessor`]. An image takes `(image_size / patch_size) ** 2` consecutive
            `config.image_token_id` placeholders, a clip one `config.audio_token_id` placeholder per audio token;
            images and clips fill them in reading order.
        pixel_values (`torch.FloatTensor` of shape `(num_images, num_channels, image_size, image_size)`, *optional*):
            Images, normalized by [`OmniDebertaImageProcessor`].
        input_features (`torch.FloatTensor` of shape `(num_clips, num_frames, num_mel_bins)`, *optional*):
            Log-mel spectrograms made by [`OmniDebertaFeatureExtractor`].
        input_features_mask (`torch.BoolTensor` of shape `(num_clips, num_frames)`, *optional*):
            True for the real mel frames of every clip.
        """
        if attention_mask is None:
            attention_mask = torch.ones_like(input_ids, dtype=torch.bool)
        modality_ids = self.get_modality_ids(input_ids)
        hidden_states = self.embeddings(
            input_ids, attention_mask, modality_ids, pixel_values, input_features, input_features_mask
        )

        positions_2d = None
        # CODEPATH: released checkpoints give image patches 2-D relative positions in some layers.
        if pixel_values is not None and self.config.relative_2d_layers:
            positions_2d = self.get_positions_2d(modality_ids)
        # CODEPATH: stage-1 checkpoints have one feed-forward block, the released ones one expert per modality.
        routing = self.get_expert_routing(input_ids, modality_ids) if self.config.modal_experts else None
        mask = create_bidirectional_mask(
            config=self.config, inputs_embeds=hidden_states, attention_mask=attention_mask
        )
        last_hidden_state = self.encoder(hidden_states, mask, positions_2d, routing, **kwargs)

        pooled = None
        if self.pooler is not None:
            rows = torch.arange(last_hidden_state.shape[0], device=last_hidden_state.device)
            pooled = last_hidden_state[rows, self.get_pool_positions(input_ids).to(rows.device)]
            pooled = self.pooler(pooled)
            pooled = F.normalize(pooled.float(), dim=-1).to(pooled.dtype)
        return BaseModelOutputWithPooling(last_hidden_state=last_hidden_state, pooler_output=pooled)


class OmniDebertaLMHead(nn.Module):
    """Word prediction head; the decoder shares its weight with the word embeddings."""

    def __init__(self, config: OmniDebertaConfig):
        super().__init__()
        self.dense = nn.Linear(config.hidden_size, config.embedding_size)
        self.transform_act_fn = ACT2FN[config.hidden_act]
        self.LayerNorm = nn.LayerNorm(config.embedding_size, eps=config.layer_norm_eps)
        self.decoder = nn.Linear(config.embedding_size, config.vocab_size, bias=False)
        self.bias = nn.Parameter(torch.zeros(config.vocab_size))

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        hidden_states = self.LayerNorm(self.transform_act_fn(self.dense(hidden_states)))
        return self.decoder(hidden_states) + self.bias


